def svg(name: str, size: int = 16, stroke: float = 1.75, fill: str = "none") -> str:
    """One inline SVG (for markup that is not sanitised, e.g. elements the page's own JS creates)."""
    inner = PATHS.get(name)
    if not inner:
        return ""
    return (f'<svg class="loa-ic" width="{size}" height="{size}" viewBox="0 0 24 24" fill="{fill}" '
            f'stroke="currentColor" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round" '
            f'aria-hidden="true">{inner}</svg>')


def icon(name: str, size: int = 16, cls: str = "") -> str:
    """One icon for HTML the app renders with st.html, which strips <svg>: an <i> that the stylesheet from css()
    paints with the icon as a CSS mask in the current text colour. `size` in px (16 default, 14 inline with
    text). Unknown names give an empty string, never raise, so a page always renders."""
    if name not in PATHS:
        return ""
    return f'<i class="loa-ic {cls}" data-ic="{name}" style="width:{size}px;height:{size}px"></i>'


def _data_uri(name: str, stroke: float = 1.75) -> str:
    body = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" '
            f'stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round">{PATHS[name]}</svg>')
    return "data:image/svg+xml;utf8," + body.replace('"', "'").replace("#", "%23").replace("<", "%3C").replace(">", "%3E")


def css(stroke: float = 1.75) -> str:
    """The stylesheet that paints every icon: a mask in currentColor, so icons follow the text colour."""
    rules = [".loa-ic{display:inline-block;vertical-align:-3px;margin-right:5px;flex:none;background-color:currentColor;"
             "-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center;"
             "-webkit-mask-size:contain;mask-size:contain;width:16px;height:16px}",
             ".loa-ic[data-ic='square']{-webkit-mask-image:none;mask-image:none;border-radius:2px}"]
    for name in PATHS:
        uri = _data_uri(name, stroke)
        rules.append(f".loa-ic[data-ic='{name}']{{-webkit-mask-image:url(\"{uri}\");mask-image:url(\"{uri}\")}}")
    return "\n".join(rules)


# Streamlit widgets (st.button icon=, st.page_link icon=, st.Page icon=) accept Material Symbols only.
MATERIAL = {"activity": ":material/monitoring:", "message-square": ":material/chat_bubble:",
            "file-text": ":material/description:", "database": ":material/database:",
            "triangle-alert": ":material/warning:", "thumbs-up": ":material/thumb_up:",
            "thumbs-down": ":material/thumb_down:", "megaphone": ":material/campaign:", "search": ":material/search:",
            "plus": ":material/add:", "bot": ":material/smart_toy:", "alarm-clock": ":material/alarm:",
            "flame": ":material/local_fire_department:", "check": ":material/check:", "square": ":material/stop:",
            "arrow-down": ":material/arrow_downward:", "refresh-cw": ":material/refresh:", "undo-2": ":material/undo:",
            "sparkles": ":material/auto_awesome:", "history": ":material/history:", "x": ":material/close:",
            "download": ":material/download:", "send": ":material/send:", "eye": ":material/visibility:",
            "presentation": ":material/co_present:", "upload": ":material/upload:", "wrench": ":material/build:",
            "circle-x": ":material/cancel:", "chevron-down": ":material/expand_more:", "share-2": ":material/share:", "eye-off": ":material/visibility_off:", "user": ":material/person:", "link-off": ":material/link_off:", "circle-check": ":material/check_circle:", "info": ":material/info:", "copy": ":material/content_copy:", "clock": ":material/schedule:"}


def material(name: str) -> str | None:
    """The Material Symbol a Streamlit widget can show for a Lucide name (None when there is no close match)."""
    return MATERIAL.get(name)
